{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Ketoconazole, the closest structural analog (Morgan 0.5532) sharing the dioxolane-dichlorophenyl-azole and aryl-piperazine-aryl ether framework, has a mean oral bioavailability of ~75% in healthy volunteers, directly supporting F>=20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Posaconazole, a close analog (Morgan 0.5288) sharing the triazolone, diaryl piperazine, and triazole-bearing cyclic ether motif, has an absolute oral bioavailability of ~50% as a delayed-release tablet in healthy volunteers, supporting F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Posaconazole oral suspension in immunocompromised patients had an estimated absolute bioavailability of 16% (8-27%), below the 20% threshold; this is formulation- and population-specific and is outweighed by tablet/healthy-volunteer data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest azole antifungal analogs, ketoconazole (~75% F) and posaconazole tablet (~50% F), provide strong transferable experimental evidence for F>=20%; the low posaconazole suspension value and unfavorable physicochemical prior are outweighed by these direct analog data.",
  "evidence_gaps": [
    "No direct human oral bioavailability data exist for the exact query molecule.",
    "Posaconazole bioavailability is strongly formulation-dependent; the query's likely formulation and dose are unspecified.",
    "The impact of replacing posaconazole's hydroxyl/difluorophenyl/tetrahydrofuran with sec-butyl/dichlorophenyl/dioxolane on solubility and absorption is not experimentally quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

